insert into "weekly_asset_performance" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-04-20', 'ภาพรวมผลตอบแทนสินทรัพย์ — สัปดาห์แห่งการฟื้นตัวของตลาดหุ้นโลกและแรงกดดันในสินค้าโภคภัณฑ์', '2026-04-20', 'ภาพรวมผลตอบแทนสินทรัพย์ — สัปดาห์แห่งการฟื้นตัวของตลาดหุ้นโลกและแรงกดดันในสินค้าโภคภัณฑ์', 'บทวิเคราะห์ผลตอบแทนสินทรัพย์รายสัปดาห์ 20–24 เมษายน 2569', '2026-04-20', '2026-04-20', '2026-04-24', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/Asset%20Performance%201.png", "width": 1672, "height": 941, "altText": "Asset Performance 1", "fileId": 357854398145, "type": "image"}'::jsonb, 'สัปดาห์แห่งการพลิกกลับ — หุ้นโลกฟื้นตัวแข็งแกร่ง ขณะที่น้ำมันดิบสหรัฐฯ ร่วงหนักสวนทิศทาง', '<p><span>ในสัปดาห์นี้ตลาดหุ้นโลกฟื้นตัวโดด เด่น โดย Global Equities ทำผลตอบแทน WTD สูงสุดที่ +3.86% ขณะที่น้ำมันดิบสหรัฐฯ ร่วงลง -14.48% WTD สะท้อนความผันผวนของตลาดสินค้าโภคภัณฑ์ นักลงทุนควรเพิ่มน้ำหนักหุ้นกลุ่มเทคโนโลยีและลดการถือครองสินทรัพย์พลังงาน</span></p>', '<h3><span>ภาพรวมผลตอบแทนสินทรัพย์</span></h3>
<p><span>ในสัปดาห์ที่ 20–24 เมษายน 2569 ตลาดสินทรัพย์โลกส่งสัญญาณฟื้นตัวในกลุ่มหุ้นอย่างชัดเจน ในขณะที่สินค้าโภคภัณฑ์ โดยเฉพาะน้ำมันดิบสหรัฐฯ เผชิญแรงขายรุนแรง สะท้อนภาพสองขั้วของตลาดในช่วงกลางไตรมาสที่สองของปี 2026</span></p>
<p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/Yuanta_Weekly_Asset_Allocation_20_24_04_2026/component_images/page_2.png" width="1282" height="890" loading="lazy" alt="Asset Classes and US Bond Yield Performance" style="height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;"></p>
<p><span>ภาพรวม WTD พบว่า Global Equities นำการฟื้นตัวด้วยผลตอบแทน +3.86% WTD สวนทางกับ US Oil ที่ร่วงหนักที่สุดในกลุ่มที่ -14.48% WTD แม้จะมี YTD range กว้างถึง 43.83% ด้านอัตราผลตอบแทนพันธบัตรสหรัฐฯ ปรับตัวลดลงเล็กน้อยทั่วทุกช่วงอายุ โดย US 2Y yield อยู่ที่ 3.71% (WTD -0.093%) US 10Y yield อยู่ที่ 4.25% (WTD -0.069%) และ US 30Y yield อยู่ที่ 4.89% (WTD -0.024%) ทั้งหมดยังอยู่ในกรอบ 1 ปีที่ผ่านมา</span></p>
<p>&nbsp;</p>
<h3><span>สินทรัพย์ที่โดดเด่น</span></h3>
<ul>
<li><span>ผู้นำ WTD: Nasdaq +6.84% WTD — กลุ่มเทคโนโลยีได้รับแรงหนุนจากผลประกอบการไตรมาสแรกที่แข็งแกร่งและการคาดการณ์อัตราดอกเบี้ยที่ผ่อนคลายลง</span></li>
<li><span>ผู้นำ YTD: KOSPI +46.93% YTD พร้อม WTD +5.68% — ตลาดหุ้นเกาหลีใต้ยังคงเป็น outperformer ระดับภูมิภาคที่โดดเด่นที่สุดในปีนี้</span></li>
<li><span>ผู้ร่วงแรงที่สุด: US Oil -14.48% WTD — ความกังวลต่ออุปทานส่วนเกินและสัญญาณชะลอตัวของอุปสงค์โลกกดดันราคาน้ำมันอย่างหนัก</span></li>
<li><span>Russell 2000 +5.56% WTD (YTD 11.89%) — หุ้นขนาดเล็กสหรัฐฯ ฟื้นตัวแข็งแกร่ง สะท้อนความเชื่อมั่นในตลาดภายในประเทศที่ดีขึ้น</span></li>
<li><span>SET Index (ไทย) -1.62% WTD และ IDX Composite (อินโดนีเซีย) -0.81% WTD — ตลาดเอเชียตะวันออกเฉียงใต้บางส่วนยังเผชิญแรงกดดันจากการไหลออกของเงินทุน</span></li>
</ul>
<p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/Yuanta_Weekly_Asset_Allocation_20_24_04_2026/component_images/page_3.png" width="1282" height="890" loading="lazy" alt="Global Stock Market YTD and WTD Performance" style="height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;"></p>
<p>&nbsp;</p>
<h3><span>ผลตอบแทนรายกลุ่มอุตสาหกรรมในสหรัฐฯ</span></h3>
<p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/Yuanta_Weekly_Asset_Allocation_20_24_04_2026/component_images/page_4.png" width="1282" height="890" loading="lazy" alt="US Sector YTD and WTD Performance 2026" style="height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;"></p>
<p><span>ในกลุ่มอุตสาหกรรมสหรัฐฯ Technology นำทัพ Growth Sector ด้วยผลตอบแทน WTD สูงสุดที่ +8.09% แม้ YTD ยังอยู่ที่ +4.73% ส่วน Financial ปรับตัวขึ้น +3.27% WTD แต่ยังติดลบ YTD ที่ -4.31% สะท้อนว่าการฟื้นตัวในสัปดาห์นี้เป็นการ rebound จากระดับต่ำ ขณะที่กลุ่ม Defensive อย่าง Utility ร่วง -1.69% WTD (YTD +8.12%) และ Consumer Staples แทบไม่เปลี่ยนแปลงที่ -0.04% WTD สะท้อนการหมุนเวียนเงินลงทุนออกจากกลุ่มป้องกันความเสี่ยงกลับสู่กลุ่ม Risk-On Energy ยังคงเป็นกลุ่มที่อ่อนแอ WTD ที่ -3.52% แม้ YTD ยังสูงถึง +22.65%</span></p>
<p>&nbsp;</p>
<h3><span>ปัจจัยขับเคลื่อนผลตอบแทน</span></h3>
<p><span>การฟื้นตัวของตลาดหุ้นโลกในสัปดาห์นี้มีปัจจัยหนุนหลักจากสัญญาณที่ดีขึ้นของผลประกอบการบริษัทจดทะเบียนในสหรัฐฯ โดยเฉพาะกลุ่มเทคโนโลยีที่ออกผลประกอบการไตรมาส 1/2026 เกินคาดการณ์ ส่งผลให้ Nasdaq พุ่งขึ้น +6.84% WTD นอกจากนี้ การปรับลดลงของอัตราผลตอบแทนพันธบัตรสหรัฐฯ ตามแนวโน้ม Soft Landing ยังช่วยเพิ่มความน่าสนใจของหุ้นกลุ่ม Growth ในขณะที่น้ำมันดิบสหรัฐฯ ร่วงหนัก -14.48% WTD จากความกังวลต่ออุปทาน OPEC+ ที่เพิ่มขึ้นและสัญญาณการชะลอตัวของเศรษฐกิจจีนที่กดดันอุปสงค์ ด้านตลาด KOSPI เกาหลีใต้ที่ยังคงแข็งแกร่ง +5.68% WTD ได้รับอานิสงส์จากกระแสการลงทุนในห่วงโซ่อุปทานเซมิคอนดักเตอร์ระดับโลก ส่วนตลาดเอเชียตะวันออกเฉียงใต้อย่าง SET และ IDX ยังเผชิญแรงกดดันจากเงินทุนต่างชาติไหลออกและความไม่แน่นอนด้านนโยบายในประเทศ</span></p>
<p>&nbsp;</p>
<h3><span>ความเสี่ยงและโอกาสการลงทุน</span></h3>
<ul>
<li><span>เพิ่มน้ำหนักหุ้นกลุ่มเทคโนโลยีสหรัฐฯ (Nasdaq / Technology Sector ETF) เนื่องจากโมเมนตัม WTD ที่แข็งแกร่ง +8.09% และผลประกอบการที่ดีกว่าคาด อาจมีความต่อเนื่องในระยะสั้น</span></li>
<li><span>พิจารณาลดการถือครอง Energy Sector เนื่องจาก WTD -3.52% สะท้อนแรงขายที่ยังคงดำเนินอยู่ แม้ YTD +22.65% จะยังเป็นบวก การกลับตัวของราคาน้ำมันอาจกดดันผลตอบแทนในระยะสั้น</span></li>
<li><span>หุ้น KOSPI เกาหลีใต้ยังคงน่าสนใจในเชิง YTD momentum (+46.93%) โดยนักลงทุนอาจพิจารณากองทุน ETF ตลาดเกาหลีใต้ หรือหุ้นกลุ่มเซมิคอนดักเตอร์ที่เกี่ยวข้อง</span></li>
<li><span>US 10Y yield ที่ปรับลดลงสู่ระดับ 4.25% (WTD -0.069%) เป็นโอกาสทยอยสะสมพันธบัตรรัฐบาลสหรัฐฯ ระยะกลาง สำหรับพอร์ตที่ต้องการกระจายความเสี่ยงจากความผันผวนของตลาดหุ้น</span></li>
<li><span>หลีกเลี่ยงการเพิ่มน้ำหนักตลาด SET Index (ไทย) ในระยะสั้น เนื่องจาก WTD -1.62% สะท้อนแรงกดดันจากเงินทุนต่างชาติไหลออก และควรรอสัญญาณการกลับมาของ Fund Flow ก่อนตัดสินใจ</span></li>
<li><span>Russell 2000 WTD +5.56% ชี้ให้เห็นโอกาสในหุ้นขนาดเล็กสหรัฐฯ หากเศรษฐกิจในประเทศยังคงแข็งแกร่ง อย่างไรก็ตาม ควรติดตามข้อมูลตลาดแรงงานและยอดค้าปลีกสหรัฐฯ ในสัปดาห์ถัดไปอย่างใกล้ชิด</span></li>
</ul>');
