insert into "weekly_asset_performance" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-06-22', 'ภาพรวมผลตอบแทนสินทรัพย์ — หุ้นเกาหลีนำตลาด ขณะที่พลังงานและทองคำปรับฐาน', '2026-06-22', 'ภาพรวมผลตอบแทนสินทรัพย์สิ้นเดือนมิถุนายน 69<div>หุ้นเกาหลีนำตลาด ในขณะที่พลังงานและทองคำปรับฐาน</div>', 'บทวิเคราะห์ผลตอบแทนสินทรัพย์รายสัปดาห์ 22–26 มิถุนายน 2569', '2026-06-22', '2026-06-22', '2026-06-26', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/2026-06-22/review-uploads/page_2.png", "altText": "", "type": "image"}'::jsonb, 'สัปดาห์แห่งความแตกต่าง &nbsp;หุ้นเกาหลีพุ่งนำโลก ขณะพลังงานและทองคำโดนแรงขาย', '<p><span>สัปดาห์นี้ตลาดหุ้นโลกฟื้นตัวโดยรวม โดย KOSPI นำด้วย WTD +11.43% ขณะที่ภาคพลังงานในสหรัฐฯ ปรับตัวลงแรงที่สุดที่ -6.57% WTD และทองคำอ่อนตัว -1.24% WTD สะท้อนภาพตลาดที่ยังมีความหลากหลายในทิศทางของแต่ละสินทรัพย์</span></p>', '<h3><span>ภาพรวมผลตอบแทนสินทรัพย์</span></h3>
<p><span>ในสัปดาห์ที่ 22–26 มิถุนายน 2569 ตลาดสินทรัพย์โลกเคลื่อนไหวในทิศทางที่หลากหลาย โดย KOSPI ทำผลตอบแทนสูงสุดในบรรดาดัชนีหุ้นทั่วโลกที่ +11.43% WTD ขณะที่ภาคพลังงานของสหรัฐฯ ร่วงหนักที่สุดในฝั่งเซกเตอร์ที่ -6.57% WTD สะท้อนภาพการหมุนเวียนสินทรัพย์ที่ชัดเจน</span></p>
<p><span>ในภาพรวม หุ้นโลก (Global Equities) ให้ผลตอบแทน WTD +0.81% และ YTD +11.48% ส่วนดัชนีดอลลาร์สหรัฐ (USD Index) ปรับตัวขึ้น WTD +0.96% โดยมี YTD +2.52% น้ำมัน (US Oil) ยังคงนำสินทรัพย์ทางเลือกในแง่ YTD สูงถึง 32.10% แม้จะชะลอลงจากจุดสูงสุด YTD ที่ 96.71% ส่วนทองคำปรับลงเล็กน้อย WTD -1.24% แต่ยังคงมี YTD สูงสุดที่ 25.31%</span></p>

<p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/2026-06-22/review-uploads/page_2.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Asset Classes and US Bond Yield Performance'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
<p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Asset Classes and US Bond Yield Performance</span></p>

<p><span>ในส่วนของอัตราผลตอบแทนพันธบัตรรัฐบาลสหรัฐฯ อายุ 2 ปี อยู่ที่ 4.18% (ช่วง 3.38%–4.19%) โดย WTD เปลี่ยนแปลง +0.092% อายุ 10 ปี อยู่ที่ 4.46% (ช่วง 3.95%–4.67%) WTD -0.028% และอายุ 30 ปี อยู่ที่ 4.90% (ช่วง 4.54%–5.18%) WTD -0.071% สะท้อนการปรับตัวลงเล็กน้อยของอัตราผลตอบแทนพันธบัตรระยะยาว</span></p>

